sys_script_client.script:
function onSubmit() {
    var status = g_form.getValue('status');
    if (status === 'resolved' || status === 'closed') {
        var notes = g_form.getValue('resolution_notes');
        var cleanText = notes ? notes.replace(/<[^>]*>/g, '').trim() : '';
        if (!cleanText) {
            g_form.addErrorMessage('Resolution Notes are required before resolving or closing a warehouse exception.');
            g_form.setMandatory('resolution_notes', true);
            return false;
        }
    }
    return true;
}
